INSERT INTO hecho_delictivo (id_hecho, id_delito) SELECT (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-11-24'  ORDER BY h.id_hecho DESC ROWS 1), dc.id_delito_cometido FROM persona p JOIN delito d ON d.codigo = 'AGR-DEL-040' JOIN clasificacion_delito c ON UPPER(TRIM(c.nombre)) = UPPER('Hurto agravado') JOIN delito_cometido dc ON dc.id_tipo_delito = d.id_delito AND dc.id_clasificacion_delito = c.id_clasificacion_delito WHERE p.nombres = 'AGR_2023_412599' AND p.apellidos = 'AGRAVIADOS' AND NOT EXISTS (SELECT 1 FROM hecho_delictivo hd WHERE hd.id_hecho = (SELECT h.id_hecho FROM hecho h  WHERE h.id_ubicacion = p.id_origen    AND h.fecha_hecho = '2023-11-24'  ORDER BY h.id_hecho DESC ROWS 1)   AND hd.id_delito = dc.id_delito_cometido);
INSERT INTO ubicacion (id_municipio, id_area_geografica, ciudad, zona, direccion_referencia) SELECT m.id_municipio, NULL, NULL, 'Ignorada', NULL FROM departamento d JOIN municipio m ON m.id_departamento = d.id_departamento WHERE UPPER(TRIM(d.nombre)) = UPPER('Quetzaltenango')   AND UPPER(TRIM(m.nombre)) = UPPER('Coatepeque')   AND NOT EXISTS (SELECT 1 FROM ubicacion u WHERE u.id_municipio = m.id_municipio AND COALESCE(u.zona, '') = 'Ignorada');
